<?php
namespace App\Services; use App\Core\Database;use App\Core\Auth;
final class ClientService{public function create(array $d):int{$pdo=Database::pdo();$pdo->beginTransaction();try{$full=trim(preg_replace('/\s+/',' ',($d['first_name']??'').' '.($d['middle_name']??'').' '.($d['last_name']??'')));if($full==='')$full=$d['full_name']??'Unnamed Client';$s=$pdo->prepare('INSERT INTO clients(tenant_id,client_no,first_name,middle_name,last_name,full_name,client_type,email,phone,phone_cell,address,city,state,zip,status,notes,created_by,updated_by,created_at,updated_at) VALUES(1,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$s->execute([$d['client_no']??('CL-'.date('YmdHis').'-'.random_int(100,999)),$d['first_name']??null,$d['middle_name']??null,$d['last_name']??null,$full,$d['client_type']??'INDIVIDUAL',$d['email']??null,$d['phone']??null,$d['phone_cell']??null,$d['address']??null,$d['city']??null,$d['state']??null,$d['zip']??null,'active',$d['notes']??null,Auth::id(),Auth::id()]);$id=(int)$pdo->lastInsertId();$this->saveCustomFields($id,$d);$pdo->prepare('INSERT IGNORE INTO communications_preferences(client_id) VALUES(?)')->execute([$id]);(new ActivityService)->record('CLIENT_CREATED','Clients','client',$id);$pdo->commit();return $id;}catch(\Throwable $e){$pdo->rollBack();throw $e;}}public function update(int $id,array $d):void{$repo=new \App\Repositories\ClientRepository;$before=$repo->find($id);if(!$before)throw new \RuntimeException('Client not found');$full=trim(preg_replace('/\s+/',' ',($d['first_name']??'').' '.($d['middle_name']??'').' '.($d['last_name']??'')));Database::pdo()->prepare('UPDATE clients SET first_name=?,middle_name=?,last_name=?,full_name=?,client_type=?,email=?,phone=?,phone_cell=?,address=?,city=?,state=?,zip=?,notes=?,updated_by=?,updated_at=NOW() WHERE id=?')->execute([$d['first_name'],$d['middle_name']??null,$d['last_name'],$full,$d['client_type'],$d['email']??null,$d['phone']??null,$d['phone_cell']??null,$d['address']??null,$d['city']??null,$d['state']??null,$d['zip']??null,$d['notes']??null,Auth::id(),$id]);$this->saveCustomFields($id,$d);$after=$repo->find($id);$changes=(new ActivityService)->diff($before,$after,['ssn_cipher','itin_cipher','ein_cipher']);(new ActivityService)->record('CLIENT_UPDATED','Clients','client',$id,$changes,'stage_3');}private function saveCustomFields(int $clientId,array $data):void{ $pdo=Database::pdo(); $fields=$pdo->query("SELECT * FROM custom_fields WHERE tenant_id=1 AND entity_type='client' AND is_active=1 ORDER BY sort_order,id")->fetchAll(); if(!$fields)return; $ins=$pdo->prepare('INSERT INTO custom_field_values(field_id,entity_id,value_text,value_json) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE value_text=VALUES(value_text),value_json=VALUES(value_json)'); foreach($fields as $f){ if(!array_key_exists($f['field_name'],$data))continue; $v=$data[$f['field_name']]; $json=in_array($f['field_type'],['checkbox','multi_select','dropdown'],true)?json_encode($v):null; $text=is_array($v)?null:(string)$v; $ins->execute([(int)$f['id'],$clientId,$text,$json]); } } public function archive(int $id):void{Database::pdo()->prepare('UPDATE clients SET deleted_at=NOW(),status="archived",updated_by=? WHERE id=?')->execute([Auth::id(),$id]);(new ActivityService)->record('CLIENT_ARCHIVED','Clients','client',$id,null,'stage_3');}}
